import type { KeyboardEvent } from 'react';

const focusElement = (element: HTMLElement | null, event: KeyboardEvent) => {
  if (element) {
    event.preventDefault();
    element.focus();
  }
};

const isActiveElement = (element: HTMLElement): boolean => {
  return element === document.activeElement;
};

function isElementRTL(element: HTMLElement): boolean {
  let currentElement: HTMLElement | null = element;
  while (currentElement) {
    if (currentElement.dir === 'rtl') {
      return true;
    }
    if (currentElement.dir === 'ltr') {
      return false;
    }
    currentElement = currentElement.parentElement;
  }
  return false;
}

const getFocusableButtons = (scope: HTMLElement): HTMLElement[] => {
  return Array.from<HTMLElement>(
    scope.querySelectorAll(`button, [role="button"], a, input`)
  ).filter(
    element =>
      !element.hasAttribute('disabled') &&
      !element.hasAttribute('data-avoid-focus') &&
      element.offsetParent !== null // Check if element is visible
  );
};

export const handleArrowKeyNavigation = ({
  e,
  scope,
}: {
  e: KeyboardEvent<HTMLDivElement>;
  scope: HTMLElement;
}) => {
  const isArrowKey = e.key === 'ArrowLeft' || e.key === 'ArrowRight';

  if (!isArrowKey || e.shiftKey) {
    return false;
  }

  // Inside an editable field (e.g. the font-size input) arrows move the caret; only navigate
  // away once the caret sits at the matching boundary. Numeric values render LTR even in RTL
  // toolbars, so the boundary check needs no RTL flip.
  const target = e.target as HTMLElement;
  if (target instanceof HTMLInputElement) {
    const { selectionStart, selectionEnd, value } = target;
    const atStart = selectionStart === 0 && selectionEnd === 0;
    const atEnd = selectionStart === value.length && selectionEnd === value.length;
    if (!(e.key === 'ArrowLeft' ? atStart : atEnd)) {
      return false;
    }
  }

  const buttons = getFocusableButtons(scope);
  const currentIndex = buttons.findIndex(isActiveElement);
  if (currentIndex === -1) {
    return false;
  }

  const nextButtonOffset = (e.key === 'ArrowLeft' ? -1 : 1) * (isElementRTL(scope) ? -1 : 1);
  const nextButtonIndex = (currentIndex + nextButtonOffset + buttons.length) % buttons.length;
  buttons[currentIndex].tabIndex = -1;
  buttons[nextButtonIndex].tabIndex = 0;
  focusElement(buttons[nextButtonIndex], e);
  return true;
};
