import cx from 'classnames';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';

import type { ToolbarButtons } from '../../../models/index.js';
import { TOOLBAR_DATA_HOOK, TOOLBAR_VISIBLE } from '../data-hooks.js';
import { MobileToolbarOverlay } from './mobile-toolbar-overlay/mobile-toolbar-overlay.js';
import styles from './RicosMobileToolbar-scss.js';

type MobileToolbarProps = {
  maxWidth: number;
  toolbarButtons: ToolbarButtons;
  type: 'floating' | 'static' | 'regular';
  ariaLabel?: string;
};

export const RicosMobileToolbar = ({
  maxWidth,
  toolbarButtons,
  type,
  ariaLabel,
}: MobileToolbarProps) => {
  const { languageDir } = useContext(RicosContext);
  const [mobileToolbar, setMobileToolbar] = useState<HTMLDivElement | null>(null);

  return (
    <div
      className={cx(styles.container, {
        [styles.regularContainer]: type === 'regular',
        [styles.floatingContainer]: type === 'floating',
        [styles.staticContainer]: type === 'static',
      })}
    >
      <MobileToolbarOverlay mobileToolbar={mobileToolbar} maxWidth={maxWidth}>
        <div
          dir={languageDir === 'rtl' ? 'rtl' : 'ltr'}
          data-hook={TOOLBAR_DATA_HOOK}
          className={cx(styles.mobileToolbar, {
            [styles.toolbarFloating]: type === 'floating',
            [styles.toolbarStatic]: type === 'static',
          })}
          style={{
            maxWidth,
          }}
          ref={ref => {
            setMobileToolbar(ref);
          }}
        >
          <div
            className={styles.buttons}
            data-hook={TOOLBAR_VISIBLE}
            role="toolbar"
            aria-label={ariaLabel}
          >
            {toolbarButtons.getButtonsElementsWithDataHook()}
          </div>
        </div>
      </MobileToolbarOverlay>
    </div>
  );
};
