import type { HideOptions, Placement, VirtualElement } from '@floating-ui/react-dom';
import { flip, hide, offset, shift, useFloating } from '@floating-ui/react-dom';
import React, { useContext, useEffect } from 'react';
import ReactDOM from 'react-dom';

import { RicosContext, ZIndexContext } from './../../../ricos-context/index.js';
import { useAnimationPausedAutoUpdate } from './../../../_shared/node-animation/use-animation-paused-auto-update.js';

import { useFloatingToolbarOffset } from './use-floating-toolbar-offset.js';

export const FloatingToolbar = ({
  children,
  hideStrategy,
  referenceElement,
  placement,
  boundary,
}: {
  children: React.ReactNode;
  hideStrategy: Exclude<HideOptions['strategy'], undefined>;
  referenceElement: VirtualElement;
  placement: Placement;
  boundary: HTMLElement;
}) => {
  const zIndexService = useContext(ZIndexContext);
  const { jsdomMode, portal } = useContext(RicosContext);
  const toolbarOffset = useFloatingToolbarOffset({ referenceElement });

  const {
    x,
    y,
    refs: { setReference, setFloating },
    elements,
    update,
    strategy,
    middlewareData,
  } = useFloating({
    placement,
    middleware: [
      shift({
        boundary,
      }),
      hide({
        strategy: hideStrategy,
        ...(hideStrategy !== 'referenceHidden' && { boundary }),
      }),
      offset(toolbarOffset),
      flip({
        boundary,
      }),
    ],
  });

  useAnimationPausedAutoUpdate({
    reference: elements.reference,
    floating: elements.floating,
    update,
  });

  useEffect(() => {
    setReference(referenceElement);
  }, [setReference, referenceElement]);

  if (!portal) {
    return null;
  }

  return ReactDOM.createPortal(
    <div
      ref={setFloating}
      style={{
        position: strategy,
        top: y ?? '',
        left: x ?? '',
        zIndex: zIndexService.getZIndex('TOOLBAR'),
        display: jsdomMode
          ? 'block'
          : middlewareData.hide?.escaped || middlewareData.hide?.referenceHidden || (!x && !y)
            ? 'none'
            : 'block',
      }}
    >
      <div data-hook="ricos-floating-toolbar" tabIndex={-1}>
        {children}
      </div>
    </div>,
    portal
  );
};
