import { useEffect, useRef, useState } from 'react';

import { EDITOR_ROOT } from './../../../ricos-editor/data-hooks.js';
import { isInsideMockModal } from './../../../_shared/is-inside-mock-modal.js';
import type { Editor } from './../../../tiptap/react/index.js';

const isInsideRicosScope = (
  target: Node | null,
  editorRoot: HTMLElement,
  portal: HTMLElement | null
) =>
  !!target &&
  (editorRoot.contains(target) ||
    (!!portal && portal.contains(target)) ||
    // The e2e/dev-only file-picker mock (used when a real Media Manager
    // isn't available) portals outside both of the above and never goes
    // through createOpenMediaManagerFn, so notifyExternalModalOpened never
    // fires for it. Same exclusion already used by useClickOutside.
    isInsideMockModal(target));

// Always holds the value as of the latest render, for reading inside a
// document-level event handler whose effect deliberately doesn't depend on
// that value (see the "Design notes" below for why).
const useLatestRef = <T>(value: T) => {
  const ref = useRef(value);
  ref.current = value;
  return ref;
};

/**
 * Whether a pointerup at `target` should dismiss, re-engage, or leave the
 * toolbar's dismissed state alone — as one ordered list of rules, so the
 * precedence between them is the code, not a paragraph next to it. Returns
 * `null` for "no change".
 */
const resolveNextDismissed = ({
  target,
  editorRoot,
  portal,
  isToolbarVisible,
  isExternalModalOpen,
  pointerDownInside,
}: {
  target: Node;
  editorRoot: HTMLElement;
  portal: HTMLElement | null;
  isToolbarVisible: boolean;
  isExternalModalOpen: boolean;
  pointerDownInside: boolean;
}): boolean | null => {
  // Highest precedence, checked before anything else: clicking back into the
  // editor's own UI always re-engages — re-clicking an already-selected node
  // doesn't reliably produce a new Selection instance, so the reset has to
  // come from the click itself, and it can't wait on `isToolbarVisible`
  // catching up to it in the same tick.
  if (editorRoot.contains(target)) {
    return false;
  }

  if (!isToolbarVisible) {
    return null;
  }

  if (isInsideRicosScope(target, editorRoot, portal) || pointerDownInside || isExternalModalOpen) {
    return null;
  }

  return true;
};

/**
 * Purely local dismiss flag — never touches `tiptapEditor.state.selection`,
 * so it can't affect the external/Wixel toolbar adapter, which derives its
 * own button set from that same selection (see rich-content-adapter.tsx).
 *
 * `isExternalModalOpen` covers modal-like flows Ricos can't see the DOM of
 * (e.g. the host's Media Manager, opened via ModalService.notifyExternalModalOpened) —
 * they can't be recognized by the editor/portal containment check below, so
 * dismissal is suppressed for as long as one is open, and reset once it closes.
 *
 * Design notes (this hook has been fixed forward several times — read this
 * before touching the effect's dependency array):
 *
 * - One `document`-level pointerdown/pointerup pair drives everything, added
 *   by an effect that depends only on `[tiptapEditor, portal]` — values
 *   stable for the toolbar's whole lifetime, on purpose. Depending on
 *   `isToolbarVisible`/`isExternalModalOpen` instead used to tear down and
 *   re-add the listeners on every visibility flip; a gesture whose own
 *   command flips visibility mid-click (e.g. inserting a table row) could
 *   have its pointerup silently dropped in the gap. Both are read via
 *   `useLatestRef` instead — see `resolveNextDismissed` for the precedence
 *   between them.
 * - `pointerDownInsideRef` remembers where the gesture's *down* half landed,
 *   for the *up* handler to check later. It's a ref rather than a plain
 *   closure variable as insurance: today the effect above rarely re-attaches,
 *   but if a future change reintroduces a dependency that re-attaches it
 *   mid-gesture, a plain variable would silently reset between a single
 *   gesture's down and up.
 */
export const useDismissPluginToolbarOnOutsideClick = (
  tiptapEditor: Editor,
  portal: HTMLElement | null,
  isToolbarVisible: boolean,
  isExternalModalOpen: boolean
): boolean => {
  const [isDismissed, setIsDismissed] = useState(false);
  const wasExternalModalOpenRef = useRef(isExternalModalOpen);
  // See "Design notes" above — kept as a ref for insurance against a future
  // dependency change reintroducing a mid-gesture effect re-attach.
  const pointerDownInsideRef = useRef(false);
  const isToolbarVisibleRef = useLatestRef(isToolbarVisible);
  const isExternalModalOpenRef = useLatestRef(isExternalModalOpen);

  // Once the external modal closes, un-dismiss so the toolbar doesn't stay
  // hidden waiting for an extra click that may never come — the block
  // itself stayed selected the whole time.
  if (wasExternalModalOpenRef.current && !isExternalModalOpen && isDismissed) {
    setIsDismissed(false);
  }
  wasExternalModalOpenRef.current = isExternalModalOpen;

  useEffect(() => {
    // The editor's own UI isn't limited to the contenteditable region
    // (`view.dom`) — footer/static/mobile toolbars render as ordinary
    // (non-portaled) siblings elsewhere under the same editor root. Walk up
    // to that root so clicking any of them doesn't look like an outside
    // click; fall back to `view.dom` if it isn't found (e.g. non-standard
    // embedding).
    const editorRoot =
      tiptapEditor.view.dom.closest<HTMLElement>(`[data-hook~="${EDITOR_ROOT}"]`) ??
      tiptapEditor.view.dom;

    const handlePointerDown = (e: PointerEvent) => {
      pointerDownInsideRef.current = isInsideRicosScope(e.target as Node, editorRoot, portal);
    };

    const handlePointerUp = (e: PointerEvent) => {
      const nextDismissed = resolveNextDismissed({
        target: e.target as Node,
        editorRoot,
        portal,
        isToolbarVisible: isToolbarVisibleRef.current,
        isExternalModalOpen: isExternalModalOpenRef.current,
        pointerDownInside: pointerDownInsideRef.current,
      });
      if (nextDismissed !== null) {
        setIsDismissed(nextDismissed);
      }
    };

    document.addEventListener('pointerdown', handlePointerDown, true);
    document.addEventListener('pointerup', handlePointerUp, true);
    return () => {
      document.removeEventListener('pointerdown', handlePointerDown, true);
      document.removeEventListener('pointerup', handlePointerUp, true);
    };
  }, [tiptapEditor, portal]);

  return isDismissed;
};
