import { More } from '@wix/wix-ui-icons-common/lazy';
import React, { forwardRef, useContext } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';
import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';

import { MoreButtonDataHook } from './data-hooks.js';

type MoreButtonProps = {
  onClick: () => void;
  shouldShowMore: boolean;
};

export const MoreButton = forwardRef<HTMLButtonElement, MoreButtonProps>(
  ({ onClick, shouldShowMore }, ref) => {
    const { t } = useContext(RicosContext);
    return (
      <ToolbarButton
        ref={ref}
        tooltip={t('MoreButton_Tooltip')}
        active={shouldShowMore}
        onClick={onClick}
        prefix={More}
        dataHook={MoreButtonDataHook}
        tabIndex={-1}
      />
    );
  }
);
