import classNames from 'classnames';
import React, { useContext, useRef } from 'react';

import { toggleQuickActionsModal } from './../../../ricos-common-plugins/quick-actions/toggle-quick-actions-modal/toggle-quick-actions-modal.js';
import {
  EditorContext,
  EditorQueryContext,
  ModalServiceContext,
  PluginsContext,
  RicosContext,
} from './../../../ricos-context/index.js';
import type { ModalService } from './../../../ricos-modals/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import { QUICK_ACTIONS_MODAL_ID } from './../../../ricos-common-plugins/quick-actions/types.js';

import { PlusButton } from './plus-button.js';
import styles from './styles/floating-add-plugin-menu-scss.js';
import { useSelectionToPosition } from './use-selection-to-position.js';

interface Props {
  supportedButtonIds?: string[];
  /**
   * Invoked on plus-button click. Receives `defaultTrigger` so callers can
   * fall through to the default open-menu behaviour.
   */
  onClick?: (defaultTrigger?: () => void) => void;
  isVisible?: () => boolean;
  dir?: string;
  nodeId?: string;
}

export const FloatingAddPluginMenu: React.FC<Props> = ({
  onClick,
  supportedButtonIds,
  isVisible = () => true,
  dir,
  nodeId,
}) => {
  const floatingMenuWrapperRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const modalService: ModalService = useContext(ModalServiceContext) || {};
  const { languageDir, isMobile } = useContext(RicosContext) || {};
  const editorQuery = useContext(EditorQueryContext);
  const { adapter } = useContext(EditorContext);
  const position = useSelectionToPosition(adapter.tiptapEditor);
  const plugins = useContext(PluginsContext);

  const FloatingButtonCustomComponent =
    plugins.getFloatingToolbarButtons().find(button =>
      button.isVisible({
        editorQuery: editorQuery.query,
        modalService,
        editor: adapter.tiptapEditor,
        nodeId,
      })
    )?.Component ?? undefined;

  const direction = dir || languageDir;

  const isModalOpen = useModalState(getIsModalOpen(QUICK_ACTIONS_MODAL_ID));

  const calcButtonPosition = (position?: DOMRect): { top: string } => {
    const buttonHeight = 20;
    const { top = 0, height = 0 } = position || {};
    const topPosition = top + height / 2 - buttonHeight / 2;
    return { top: `${topPosition}px` };
  };

  // The legacy `SIDE.onClick` signature is `() => void`. Callers that want the
  // default open-menu behaviour to run (either instead of or in addition to their
  // custom logic) receive it as an argument — the V2 `insert.plusButton.onTrigger`
  // adapter relies on this. Legacy consumers that declared `onClick: () => void`
  // simply ignore the extra arg.
  const defaultTrigger = () =>
    toggleQuickActionsModal({
      modalService,
      referenceElement: floatingMenuWrapperRef.current,
      isMobile,
      supportedPlugins: supportedButtonIds,
    });
  const onPlusButtonClick = () => (onClick ? onClick(defaultTrigger) : defaultTrigger());

  return !isMobile ? (
    <div
      className={classNames(styles.floatingAddPluginMenu_wrapper)}
      ref={floatingMenuWrapperRef}
      data-hook="floating-add-plugin-menu"
      dir={direction}
    >
      {!!position && FloatingButtonCustomComponent ? (
        <FloatingButtonCustomComponent
          className={classNames(
            styles.floatingAddPluginMenu_plus_button_position,
            styles[direction]
          )}
          position={calcButtonPosition(position)}
        />
      ) : !!position && isVisible() ? (
        <PlusButton
          onClick={onPlusButtonClick}
          position={calcButtonPosition(position)}
          ref={buttonRef}
          rotate={isModalOpen}
          direction={direction}
        />
      ) : null}
    </div>
  ) : null;
};
