import React, { useContext, useEffect, useRef, useState } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';

import type { ToolbarButtons } from '../../../models/index.js';
import type { OverflownItemsPosition } from '../../../types.js';
import { MoreButton } from '../../buttons/index.js';
import { useSizeCalculator } from '../../UseSizeCalculator/index.js';
import { TOOLBAR_VISIBLE } from '../data-hooks.js';
import { OverflownButtonsToolbar } from './data-hooks.js';
import { handleArrowKeyNavigation } from './handle-arrow-navigation.js';
import { OverflownButtons } from './overflown-buttons.js';
import { RicosDesktopToolbarWrapper } from './ricos-desktop-toolbar-wrapper.js';
import styles from './RicosDesktopToolbar-scss.js';
import { useRicosDesktopToolbarActions } from './use-ricos-desktop-toolbar-actions.js';

export const RicosDesktopToolbar = ({
  type,
  maxWidth,
  toolbarButtons,
  onlyShownButtons,
  isRTL,
  overflownItemsPosition,
  alignment,
  ariaLabel,
}: {
  type: 'floating' | 'static' | 'regular';
  maxWidth: number;
  toolbarButtons: ToolbarButtons;
  onlyShownButtons?: string[];
  isRTL: boolean;
  overflownItemsPosition?: OverflownItemsPosition;
  alignment?: string;
  ariaLabel?: string;
}) => {
  const [moreButton, setMoreButton] = useState<HTMLButtonElement | null>(null);
  const [toolbarElement, setToolbarElement] = useState<HTMLDivElement | null>(null);
  // This toolbar's own portaled overflow menu, for the wrapper's click-outside guard.
  const overflownToolbarRef = useRef<HTMLDivElement | null>(null);
  const showMoreAbove = overflownItemsPosition === 'top';
  const { portal, lastInteraction } = useContext(RicosContext);

  const { shouldShowMore, closeToolbar, onClickOutside, toggleMoreItems } =
    useRicosDesktopToolbarActions();

  const { data, OverflowCalculator } = useSizeCalculator({
    width: maxWidth,
    toolbarButtons,
    onlyShownButtons,
  });

  // Auto-focus first overflow button when more menu opens
  useEffect(() => {
    if (shouldShowMore && data && portal && lastInteraction === 'keyboard') {
      const firstOverflowButtonDataHook = data.overflownButtons.getFirstButtonDataHook();
      if (firstOverflowButtonDataHook) {
        setTimeout(() => {
          const firstOverflowButton = portal.querySelector(
            `[data-hook~="${OverflownButtonsToolbar}"] [data-hook~="${firstOverflowButtonDataHook}"]`
          ) as HTMLElement;
          if (firstOverflowButton) {
            firstOverflowButton.focus();
          }
        }, 0);
      }
    }
  }, [shouldShowMore, data, portal]);

  const wrapperProps = {
    type,
    isRTL,
    onKeyDown: (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (type === 'floating' && (e.key === 'Escape' || e.key === 'Tab')) {
        e.preventDefault();
        closeToolbar(moreButton);
      }
    },
    onClickOutside,
    overflownToolbarRef,
  };

  return (
    <RicosDesktopToolbarWrapper {...wrapperProps}>
      <OverflowCalculator />
      {!!data && (
        <div
          ref={setToolbarElement}
          className={styles.toolbarVisible}
          style={alignment && alignment !== 'left' ? { width: '100%' } : undefined}
          data-hook={TOOLBAR_VISIBLE}
          role="toolbar"
          aria-label={ariaLabel}
          onKeyDown={e => {
            if (toolbarElement) {
              handleArrowKeyNavigation({
                e,
                scope: toolbarElement,
              });
            }
          }}
        >
          {!!moreButton && (
            <OverflownButtons
              shouldShowMore={shouldShowMore}
              overflownButtons={data.overflownButtons}
              showMoreAbove={showMoreAbove}
              attachTo={moreButton}
              onTabPress={() => closeToolbar(moreButton)}
              toolbarRef={overflownToolbarRef}
            />
          )}
          {!data.visibleButtons.isEmpty() && (
            <div
              className={styles.visibleItems}
              style={{
                justifyContent: alignment,
                ...(alignment && alignment !== 'left' ? { width: '100%' } : {}),
              }}
            >
              {data.visibleButtons.getButtonsElementsWithDataHook()}
              {!data.overflownButtons.isEmpty() && (
                <MoreButton
                  ref={setMoreButton}
                  key="more-button"
                  onClick={toggleMoreItems}
                  shouldShowMore={shouldShowMore}
                />
              )}
            </div>
          )}
        </div>
      )}
    </RicosDesktopToolbarWrapper>
  );
};
