import { fromEntries } from './../ricos-content/lib/utils.js';
import type { IToolbarItemConfigTiptap, TextButton, ToolbarButton } from './../ricos-types/index.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';

export const toResolvedAttributes = (
  button: TextButton | ToolbarButton,
  options?: {
    disabled: boolean;
  }
): IToolbarItemConfigTiptap['attributes'] => {
  const resolvedAttributes = Object.entries(button.attributes || {}).map(([key, value]) => {
    return [key, value];
  });
  if (options?.disabled) {
    resolvedAttributes.push(['disabled', isAlwaysVisible]);
  }
  return fromEntries(resolvedAttributes);
};
