import type { FC } from 'react';
import React, { useContext, useMemo, useState } from 'react';

import { EditorContext, RicosContext, useTrackRender } from './../../../ricos-context/index.js';
import { ToolbarType } from './../../../ricos-types/index.js';
import { Toolbar } from './../../components/Toolbar/index.js';

import { MaxWidthCalculationWrapper } from '../../components/MaxWidthCalculationWrapper/max-width-calculation-wrapper.js';
import { useToolbarsItemsConfig } from '../formatting/use-toolbars-items-config.js';
import { useIsToolbarEmpty } from '../use-is-toolbar-empty.js';
import { MOBILE_TOOLBAR } from './data-hooks.js';
import { mobileItemsRenderers } from './mobile-renderers.js';

export const MobileToolbar: FC = () => {
  useTrackRender('Mobile toolbar');
  const toolbarItemsConfig = useToolbarsItemsConfig(ToolbarType.MOBILE);

  const { isMobile, languageDir, t } = useContext(RicosContext);

  const {
    adapter: { tiptapEditor },
  } = useContext(EditorContext);
  const [maxWidth, setMaxWidth] = useState(tiptapEditor.view.dom.clientWidth);

  const toolbarItemsRenderers = useMemo(() => mobileItemsRenderers, []);

  const isMobileToolbarEmpty = useIsToolbarEmpty(ToolbarType.MOBILE);

  if (isMobileToolbarEmpty) {
    return null;
  }

  return (
    <MaxWidthCalculationWrapper
      setMaxWidth={setMaxWidth}
      data-hook={MOBILE_TOOLBAR}
      dir={languageDir}
    >
      <Toolbar
        type="regular"
        maxWidth={maxWidth}
        isMobile={isMobile}
        toolbarItemsConfig={toolbarItemsConfig}
        toolbarItemsRenderers={toolbarItemsRenderers}
        ariaLabel={t('FormattingToolbar_AriaLabel')}
      />
    </MaxWidthCalculationWrapper>
  );
};
