import type { ComponentType } from 'react';
import React from 'react';

import type { IToolbarItem, ToolbarButtonRenderers } from './../ricos-types/index.js';

import { CustomButton } from './components/buttons/index.js';

type CustomIToolbarItem = IToolbarItem & { presentation?: { component?: ComponentType } };

export const customToolbarButtonItemRenderer: ToolbarButtonRenderers = {
  custom: (toolbarItem: CustomIToolbarItem) => {
    const CustomComponent = toolbarItem.presentation?.component ?? React.Fragment;
    return (
      <CustomButton toolbarItem={toolbarItem}>
        <CustomComponent />
      </CustomButton>
    );
  },
};
