import React, { useContext, useEffect, useMemo } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type { IToolbarItemConfigTiptap, ToolbarButtonRenderers } from './../../../ricos-types/index.js';

import { ToolbarButtons } from '../../models/index.js';
import type { RicosToolbar } from '../../ricos-toolbar.js';
import type { OverflownItemsPosition } from '../../types.js';
import { filterExcessiveToolbarSeparators } from './filter-excessive-toolbar-separators.js';
import { RicosDesktopToolbar } from './RicosDesktopToolbar/ricos-desktop-toolbar.js';
import { RicosMobileToolbar } from './RicosMobileToolbar/ricos-mobile-toolbar.js';
import { transformItemToButton } from './transform-item-to-button.js';
import { useCreateRicosToolbar } from './use-create-ricos-toolbar.js';

type ToolbarProps = {
  toolbarItemsRenderers: ToolbarButtonRenderers;
  toolbarItemsConfig: IToolbarItemConfigTiptap[];
  onLoad?: (toolbar: RicosToolbar) => void;
  alignment?: string;
  type: 'floating' | 'static' | 'regular';
  overflownItemsPosition?: OverflownItemsPosition;
  onlyShownButtons?: string[];
  isMobile: boolean;
  maxWidth: number;
  ariaLabel?: string;
};

export const Toolbar = ({
  toolbarItemsConfig,
  onLoad,
  toolbarItemsRenderers,
  overflownItemsPosition,
  type,
  alignment,
  onlyShownButtons,
  isMobile,
  maxWidth,
  ariaLabel,
}: ToolbarProps) => {
  const toolbar = useCreateRicosToolbar(toolbarItemsConfig);
  const { languageDir } = useContext(RicosContext);
  const isRTL = languageDir === 'rtl';

  const visibleToolbarButtons = toolbar.toolbarItems.filter(item => {
    const { disabled, visible, alwaysVisible } = item.attributes;

    if (alwaysVisible) {
      return true;
    }

    return type === 'floating' ? !disabled && visible : visible;
  });

  // Create a stable key for useMemo to avoid array size warnings
  // Include both IDs and disabled state to properly track changes
  const visibleButtonsKey = visibleToolbarButtons
    .map(item => `${item.id}:${item.attributes.disabled ? '1' : '0'}`)
    .join('|');

  const toolbarButtons = useMemo(() => {
    const visibleButtons = visibleToolbarButtons.map((toolbarItem, index) => {
      toolbarItem.presentation.tabIndex = index === 0 ? 0 : -1;
      return transformItemToButton(toolbarItem, toolbarItemsRenderers);
    });
    const filtered = filterExcessiveToolbarSeparators(visibleButtons);
    return new ToolbarButtons(filtered);
  }, [visibleButtonsKey, toolbarItemsRenderers]);

  useEffect(() => {
    onLoad?.(toolbar);
  }, [toolbar]);

  useEffect(() => {
    return () => {
      toolbar.destroyToolbarItems();
    };
  }, [toolbar]);

  if (isMobile) {
    return (
      <RicosMobileToolbar
        maxWidth={maxWidth}
        toolbarButtons={toolbarButtons}
        type={type}
        ariaLabel={ariaLabel}
      />
    );
  }

  return (
    <RicosDesktopToolbar
      type={type}
      maxWidth={maxWidth}
      toolbarButtons={toolbarButtons}
      isRTL={isRTL}
      onlyShownButtons={onlyShownButtons}
      overflownItemsPosition={overflownItemsPosition}
      alignment={alignment}
      ariaLabel={ariaLabel}
    />
  );
};
