// Deprecated INSERT_PLUGIN_BUTTONS members (e.g. MAP) have no schema mapping and are excluded here
export const supportedInsertButtonNames: string[] = Object.values(INSERT_PLUGIN_BUTTONS).filter(
  buttonName => buttonName in INSERT_BUTTON_TO_SCHEMA_ID
);

// warn at most once per unknown id — unthrottled logs here previously caused console flood on every render
const warnedIds = new Set<string>();

export const toInsertSchemaBasedId = (insertButtonId: string): string | undefined => {
  const schemaBasedId = INSERT_BUTTON_TO_SCHEMA_ID[insertButtonId];

  if (!schemaBasedId && !warnedIds.has(insertButtonId)) {
    warnedIds.add(insertButtonId);
    console.warn(
      `toInsertSchemaBasedId: unknown insert button id "${insertButtonId}" — omitting it from the insert toolbar. Expected a supported member of INSERT_PLUGIN_BUTTONS.`
    );
  }

  return schemaBasedId;
};
