import React, { useContext, useEffect, useMemo, useState } from 'react';
import { isDefined } from 'ts-is-present';

import { EditorContext, PluginsEventsContext, RicosContext } from './../../../ricos-context/index.js';
import { getToolbarSettings, useToolbarSettings } from './../../../ricos-context/toolbar-context.js';
import type { PluginsEvents } from './../../../ricos-plugins/index.js';
import { getButtonsListFromConfig } from './../../../ricos-plugins/toolbar-utils/get-buttons-list-from-config.js';
import type {
  AddButton,
  IToolbarItemConfigTiptap,
  TFunction,
  ToolbarSettingsFunctions,
} from './../../../ricos-types/index.js';
import { ToolbarType } from './../../../ricos-types/index.js';
import { isAlwaysVisible } from './../../../_shared/resolvers/is-always-visible.js';
import { TOOLBARS } from './../../../editor-common/index.js';

import type { OverflownItemsPosition, ToolbarItemProps } from '../../types.js';
import { ToggleButton } from '../buttons/index.js';
import { Toolbar } from '../Toolbar/toolbar.js';
import styles from './insert-plugin-toolbar-scss.js';

interface Props {
  buttons: AddButton[];
  onlyShownButtons?: string[];
  type: 'floating' | 'static' | 'regular';
  referenceElement?: React.RefObject<HTMLElement>;
  onButtonClick: (button: AddButton, e: Event) => void;
  overflownItemsPosition?: OverflownItemsPosition;
  options?: { disabled: boolean };
  alignment?: string;
}

export const InsertPluginToolbar: React.FC<Props> = ({
  buttons,
  type,
  onButtonClick,
  overflownItemsPosition,
  options,
  alignment,
  onlyShownButtons,
}) => {
  const { adapter } = useContext(EditorContext);
  const toolbarSettings = useToolbarSettings(getToolbarSettings(ToolbarType.INSERT_PLUGIN));

  const { isMobile, t } = useContext(RicosContext);
  const pluginsEvents = useContext(PluginsEventsContext);
  const [wrapper, setWrapper] = useState<null | HTMLDivElement>(null);
  const [maxWidth, setMaxWidth] = useState(adapter.tiptapEditor.view.dom.clientWidth);

  useEffect(() => {
    if (!wrapper || !window?.ResizeObserver) {
      return;
    }

    setMaxWidth(adapter.tiptapEditor.view.dom.clientWidth);

    const resizeObserver = new ResizeObserver(() => {
      setMaxWidth(adapter.tiptapEditor.view.dom.clientWidth);
    });

    resizeObserver.observe(wrapper);

    return () => resizeObserver.disconnect();
  }, [buttons, options, isMobile, wrapper]);

  const renderers = useMemo(
    () =>
      buttons.reduce((result, addButton) => {
        const button = addButton;
        return {
          ...result,
          [button.id]: ({ toolbarItem, tabIndex }: ToolbarItemProps) => (
            <ToggleButton
              toolbarItem={toolbarItem}
              tabIndex={tabIndex}
              onClick={(e: $TSFixMe) => onButtonClick(addButton, e)}
            />
          ),
        };
      }, {}),
    [buttons]
  );

  const config = useMemo(
    () => toToolbarButtonsConfig(buttons, t, pluginsEvents, toolbarSettings, isMobile, options),
    [isMobile, options, buttons, t, pluginsEvents, toolbarSettings]
  );

  return (
    <div className={styles.wrapper} ref={setWrapper}>
      <Toolbar
        type={type}
        maxWidth={maxWidth}
        toolbarItemsConfig={config}
        onlyShownButtons={onlyShownButtons}
        toolbarItemsRenderers={renderers}
        isMobile={false}
        overflownItemsPosition={overflownItemsPosition}
        alignment={alignment}
        ariaLabel={t('PluginToolbar_AriaLabel')}
      />
    </div>
  );
};

const toToolbarButtonsConfig = (
  buttons: AddButton[],
  t: TFunction,
  pluginsEvents: PluginsEvents,
  toolbarSettingsFunctions: ToolbarSettingsFunctions | undefined,
  isMobile: boolean,
  options?: { disabled: boolean }
): IToolbarItemConfigTiptap[] => {
  const buttonType = isMobile ? 'mobile' : 'desktop';

  if (!toolbarSettingsFunctions) {
    return buttons.map(b => toToolbarItemConfig(b, t, pluginsEvents, options));
  }

  const buttonsPerType = getButtonsListFromConfig(toolbarSettingsFunctions, buttonType);

  if (!Array.isArray(buttonsPerType) || buttonsPerType.length === 0) {
    return buttons.map(b => toToolbarItemConfig(b, t, pluginsEvents, options));
  }

  return buttonsPerType
    .map(b => buttons.find(btn => btn.label === b))
    .filter(isDefined)
    .map(b => toToolbarItemConfig(b, t, pluginsEvents, options));
};

const toToolbarItemConfig = (
  button: AddButton,
  t: TFunction,
  pluginsEvents: PluginsEvents,
  options?: { disabled: boolean }
): IToolbarItemConfigTiptap => {
  const disabled = options?.disabled;
  return {
    id: button.id,
    type: 'toggle',
    presentation: {
      tooltip: t(button.tooltip),
      icon: button.icon,
      dataHook: button.dataHook,
    },
    attributes: disabled
      ? {
          visible: isAlwaysVisible,
          disabled: () => disabled,
        }
      : { visible: isAlwaysVisible },
    commands: {
      click:
        ({ publicCommands }) =>
        () => {
          pluginsEvents.publishers.byTopic('ricos.toolbars.functionality.buttonClick').publish({
            toolbarType: TOOLBARS.SIDE,
            buttonId: button.id,
          });
          pluginsEvents.publishPluginAdd({
            pluginId: button.id,
            entryPoint: TOOLBARS.PLUGIN_MENU,
          });
          button.command({ publicCommands });
        },
    },
  };
};
