import type { IContent, IEventEmitter, Resolver } from './../ricos-types/index.js';
import type { Editor } from './../tiptap/core/index.js';
import type { Node } from './../tiptap/pm/model.js';

import { EventEmitter } from './lib/event-emitter.js';
import type { ContentServices } from './types.js';

export class Content<T = Node[]> extends EventEmitter implements IContent<T>, IEventEmitter {
  static EVENTS = {
    contentChangeEvent: 'contentChange',
  };

  editor: any;

  private constructor(
    private content: T,
    private services: ContentServices
  ) {
    super();
  }

  resolve<T>(resolver: Resolver<T>): T {
    return resolver(this.content as Node[], this.services, this.editor);
  }

  //TODO: should be removed
  forceUpdate() {
    this.update(this.content, this.editor);
  }

  update(content: T, editor?: Editor) {
    this.content = content;
    this.editor = editor;
    this.emit(Content.EVENTS.contentChangeEvent);
  }

  get value() {
    return this.content;
  }

  isEmpty() {
    return !!this.content;
  }

  static create<T>(content: T, services: ContentServices) {
    return new Content(content, services);
  }
}
