import React, { useContext } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';
import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';

import type { ToolbarItemProps } from '../../../types.js';

export const ToggleButton: React.FC<ToolbarItemProps> = ({ toolbarItem, onClick, dataHook }) => {
  const { t } = useContext(RicosContext);

  const tooltip = toolbarItem.presentation?.tooltip;

  return (
    <ToolbarButton
      active={toolbarItem.attributes.active}
      disabled={toolbarItem.attributes.disabled}
      tooltip={t(tooltip)}
      onClick={onClick}
      prefix={toolbarItem.presentation?.icon}
      dataHook={`${dataHook} ${toolbarItem.attributes.active ? 'active' : 'disabled'}`}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
