import type { FC } from 'react';
import React, { useCallback, useContext, useMemo } from 'react';

import {
  EditorContext,
  EditorQueryContext,
  PluginsContext,
  PluginsEventsContext,
  RicosContext,
  useTrackRender,
} from './../../../ricos-context/index.js';
import { getToolbarSettings, useToolbarSettings } from './../../../ricos-context/toolbar-context.js';
import type { AddButton, PublicCommands } from './../../../ricos-types/index.js';
import { ToolbarType } from './../../../ricos-types/index.js';
import { getPluginIdByInsertPlugin } from './../../../_shared/get-plugin-id-by-insert-plugin.js';
import { TOOLBARS } from './../../../editor-common/index.js';

import { InsertPluginToolbar } from '../../components/InsertPluginToolbar/insert-plugin-toolbar.js';
import { useIsToolbarEmpty } from '../use-is-toolbar-empty.js';
import { FOOTER_TOOLBAR } from './data-hooks.js';
import styles from './FooterToolbar-scss.js';

export const FooterToolbar: FC = () => {
  useTrackRender('Footer toolbar');

  const plugins = useContext(PluginsContext);
  const { languageDir } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const editorQuery = useContext(EditorQueryContext);
  const { footerToolbarConfig } = useToolbarSettings(getToolbarSettings(ToolbarType.FOOTER)) ?? {};
  const pluginsEvents = useContext(PluginsEventsContext);

  const onlyShownButtons = useMemo(
    () => footerToolbarConfig?.pluginsToDisplayInToolbar?.map(getPluginIdByInsertPlugin),
    [footerToolbarConfig?.pluginsToDisplayInToolbar]
  );

  const addButtons = useMemo(() => plugins.getAddButtons(), [plugins]);

  const selection = editorQuery.selection().doc?.children?.[0];
  const disabled = plugins.isFooterToolbarDisabled(selection);
  const options = useMemo(
    () => ({
      disabled,
    }),
    [disabled]
  );

  const onButtonClick = useCallback(
    (addButton: AddButton, event: Event) => {
      const getClickHandler =
        (publicCommands: PublicCommands, referenceElement?: HTMLElement | null) => () => {
          addButton.command({ publicCommands, referenceElement });

          pluginsEvents.publishPluginAdd({
            pluginId: addButton.id,
            entryPoint: TOOLBARS.FOOTER,
          });
        };
      return getClickHandler(getPublicCommands?.(), event.target as HTMLElement)();
    },
    [getPublicCommands, pluginsEvents]
  );

  const isToolbarEmpty = useIsToolbarEmpty(ToolbarType.FOOTER);

  if (isToolbarEmpty) {
    return null;
  }

  return (
    <div className={styles.footerToolbar} data-hook={FOOTER_TOOLBAR}>
      <InsertPluginToolbar
        type="regular"
        buttons={addButtons}
        onButtonClick={onButtonClick}
        onlyShownButtons={onlyShownButtons}
        overflownItemsPosition="top"
        options={options}
        alignment={languageDir === 'rtl' ? 'right' : 'left'}
      />
    </div>
  );
};
