import { useContext, useMemo } from 'react';

import { EditorContext, EditorQueryContext, RicosContext } from './../../../ricos-context/index.js';
import { useModalService } from './../../../ricos-modals/index.js';
import type { IToolbarItemConfigTiptap } from './../../../ricos-types/index.js';

import { RicosToolbar } from '../../ricos-toolbar.js';
import { ToolbarItemCreator } from '../../toolbar-item-creator.js';

export const useCreateRicosToolbar = (itemConfig: IToolbarItemConfigTiptap[]) => {
  const { content } = useContext(RicosContext);
  const editorQuery = useContext(EditorQueryContext);
  const {
    adapter: { tiptapEditor },
    getPublicCommands,
  } = useContext(EditorContext);
  const modalService = useModalService();

  const toolbar = useMemo(() => {
    return RicosToolbar.create({
      toolbarItemCreators: itemConfig.map(config => ToolbarItemCreator.create(config)),
      content,
      tiptapEditor,
      editorQuery,
      modalService,
      publicCommands: getPublicCommands(),
    });
  }, [itemConfig, content, tiptapEditor, modalService]);

  if (toolbar.shouldCreateToolbarItems()) {
    toolbar.createToolbarItems();
  }

  toolbar.update();

  return toolbar;
};
