import classNames from 'classnames';
import React from 'react';

import { ClickOutside } from './../../../../ui-components/ClickOutside/click-outside.js';

import { TOOLBAR_DATA_HOOK } from '../data-hooks.js';
import styles from './RicosDesktopToolbarWrapper-scss.js';
import type { useRicosDesktopToolbarActions } from './use-ricos-desktop-toolbar-actions.js';

/**
 * The overflown-buttons toolbar is a React child of this wrapper but renders through a
 * portal, so it is not a DOM descendant. The toolbars-v3 `ClickOutside` this replaced
 * detected "inside" through React's synthetic event tree, which does cross portals;
 * the `ui-components` one uses DOM containment, so the portal has to be re-admitted
 * explicitly — otherwise pressing an overflown button closes the menu out from under
 * the press and the button never receives its click. The check is against this
 * toolbar's own overflow element (not the shared data-hook, which any open overflow
 * menu in the document would match), so one toolbar's menu never shields another's.
 */
const isInsideOwnOverflownButtons = (
  overflownToolbar: HTMLDivElement | null,
  target: EventTarget | null
) => target instanceof Node && overflownToolbar !== null && overflownToolbar.contains(target);

export const RicosDesktopToolbarWrapper = ({
  type,
  isRTL,
  children,
  onKeyDown,
  onClickOutside,
  overflownToolbarRef,
}: {
  type: 'floating' | 'static' | 'regular';
  isRTL: boolean;
  children: React.ReactNode;
  onKeyDown: (e: React.KeyboardEvent<HTMLDivElement>) => void;
  onClickOutside: ReturnType<typeof useRicosDesktopToolbarActions>['onClickOutside'];
  overflownToolbarRef: React.RefObject<HTMLDivElement>;
}) => {
  return (
    <div
      onKeyDown={onKeyDown}
      role="toolbar"
      dir={isRTL ? 'rtl' : 'ltr'}
      data-hook={TOOLBAR_DATA_HOOK}
      className={classNames(styles.toolbar, {
        [styles.toolbarFloating]: type === 'floating',
        [styles.toolbarStatic]: type === 'static',
      })}
    >
      {/* `pointerdown` keeps the previous implementation's timing: it closed the toolbar
          on `mousedown`, not on release. */}
      <ClickOutside
        triggerOn="pointerdown"
        onClickOutside={e => {
          if (!isInsideOwnOverflownButtons(overflownToolbarRef.current, e.target)) {
            onClickOutside();
          }
        }}
      >
        {children}
      </ClickOutside>
    </div>
  );
};
