import React, { useContext } from 'react';

import { ModalServiceContext, RicosContext } from './../../../../ricos-context/index.js';
import type { ModalService } from './../../../../ricos-modals/index.js';
import type { IToolbarItem } from './../../../../ricos-types/index.js';
import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';
import { toggleQuickActionsModal } from './../../../../ricos-common-plugins/quick-actions/toggle-quick-actions-modal/toggle-quick-actions-modal.js';

import classes from './AddPluginMenuMobileButton-scss.js';

export const AddPluginMenuMobileButton: React.FC<{ toolbarItem: IToolbarItem }> = ({
  toolbarItem,
}) => {
  const { isMobile } = useContext(RicosContext);
  const modalService: ModalService = useContext(ModalServiceContext) || {};

  return (
    <ToolbarButton
      dataHook="add-plugin-button-mobile"
      onClick={() => {
        toggleQuickActionsModal({ modalService, referenceElement: null, isMobile });
      }}
      className={classes.toggleButton}
      prefix={toolbarItem.presentation?.icon}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
