import React, { useCallback, useState } from 'react';

import type { ToolbarButtons } from '../../../models/index.js';
import { FloatingToolbar } from '../../FloatingToolbar/floating-toolbar.js';
import { OverflownButtonsToolbar } from './data-hooks.js';
import { handleArrowKeyNavigation } from './handle-arrow-navigation.js';
import styles from './OverflownButtons-scss.js';

export const OverflownButtons = ({
  shouldShowMore,
  overflownButtons,
  showMoreAbove,
  attachTo,
  onTabPress,
  toolbarRef,
}: {
  shouldShowMore: boolean;
  overflownButtons: ToolbarButtons;
  showMoreAbove: boolean;
  attachTo: HTMLButtonElement;
  onTabPress: () => void;
  /** Exposes the overflow toolbar element to the owning toolbar's click-outside guard. */
  toolbarRef: React.MutableRefObject<HTMLDivElement | null>;
}) => {
  const [toolbarElement, setToolbarElement] = useState<HTMLDivElement | null>(null);

  // Stable identity, so React doesn't detach and reattach the ref (a transient null plus
  // redundant state updates) on every rerender.
  const setOverflownToolbarElement = useCallback(
    (element: HTMLDivElement | null) => {
      setToolbarElement(element);
      toolbarRef.current = element;
    },
    [toolbarRef]
  );

  const showOverflowButtons = shouldShowMore && !overflownButtons.isEmpty() && !!attachTo;

  if (!showOverflowButtons) {
    return null;
  }

  const renderVertical = showMoreAbove ? 'top' : 'bottom';

  return (
    <FloatingToolbar
      hideStrategy="referenceHidden"
      referenceElement={attachTo}
      boundary={document.body}
      placement={`${renderVertical}-start`}
    >
      <div
        ref={setOverflownToolbarElement}
        className={styles.moreItems}
        data-hook={OverflownButtonsToolbar}
        role="toolbar"
        onKeyDown={e => {
          if (e.key === 'Tab') {
            e.preventDefault();
            e.stopPropagation();
            onTabPress();
          }
          if (toolbarElement) {
            handleArrowKeyNavigation({
              e,
              scope: toolbarElement,
            });
          }
        }}
      >
        <div className={styles.overflownItems}>
          {overflownButtons.getButtonsElementsWithDataHook()}
        </div>
      </div>
    </FloatingToolbar>
  );
};
