import type { ReactChild } from 'react';
import React from 'react';

import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';

import type { ToolbarItemProps } from '../../../types.js';

export const CustomButton = ({
  toolbarItem,
  dataHook,
  children,
}: ToolbarItemProps & { children: ReactChild }) => {
  return (
    <ToolbarButton
      active={toolbarItem.attributes.active}
      disabled={toolbarItem.attributes.disabled}
      onClick={e => toolbarItem.commands?.click?.(e)}
      dataHook={dataHook}
      tooltip={toolbarItem.presentation?.tooltip}
      prefix={React.useCallback(() => children, [children])}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
