import React, { useCallback, useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import { ToolbarButtons } from '../../models/index.js';

type SizeResult = {
  visibleButtons: ToolbarButtons;
  overflownButtons: ToolbarButtons;
};

type SizeCalculatorProps = {
  width: number;
  toolbarButtons: ToolbarButtons;
  onlyShownButtons?: string[];
};

const MORE_BUTTON_WIDTH = 30;
const GAP_BETWEEN_BUTTONS = 4;

const getButtonsToRender = (toolbarButtons: ToolbarButtons, onlyShownButtons?: string[]) =>
  new ToolbarButtons(
    toolbarButtons.toolbarButtons
      .filter(button => onlyShownButtons === undefined || onlyShownButtons.includes(button.getId()))
      .sort(
        (a, b) =>
          (onlyShownButtons?.findIndex(id => id === a.getId()) ?? 0) -
          (onlyShownButtons?.findIndex(id => id === b.getId()) ?? 0)
      )
  );

const getAlwaysOverflownButtons = (toolbarButtons: ToolbarButtons, onlyShownButtons?: string[]) =>
  toolbarButtons.toolbarButtons.filter(
    button => onlyShownButtons !== undefined && !onlyShownButtons.includes(button.getId())
  );

// Optimistic first render, before the hidden measurer below has had a chance
// to mount and measure real button widths: assume nothing overflows on
// width grounds yet (only respecting `onlyShownButtons`-forced overflow).
// Without this, `data` starts `undefined` and the toolbar's whole
// `TOOLBAR_VISIBLE` marker (and every button in it) is absent from the DOM
// for at least one extra render+effect cycle after every mount — e.g. after
// a plugin toolbar unmounts on blur and remounts on reselection — which is
// enough to flake a UI test that clicks a toolbar button right after
// reselecting (see table-style-inheritance sled3 spec).
const getInitialSizeResult = (
  toolbarButtons: ToolbarButtons,
  onlyShownButtons?: string[]
): SizeResult => ({
  visibleButtons: getButtonsToRender(toolbarButtons, onlyShownButtons),
  overflownButtons: new ToolbarButtons(getAlwaysOverflownButtons(toolbarButtons, onlyShownButtons)),
});

const Overflow = ({
  width,
  toolbarButtons,
  onChange,
  onlyShownButtons,
}: {
  width: number;
  toolbarButtons: ToolbarButtons;
  onChange: (result: SizeResult) => void;
  onlyShownButtons?: string[];
}) => {
  const { jsdomMode } = useContext(RicosContext);
  const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);
  const buttonsToRender = getButtonsToRender(toolbarButtons, onlyShownButtons);
  const alwaysOverflownButtons = getAlwaysOverflownButtons(toolbarButtons, onlyShownButtons);
  useEffect(() => {
    let sumVisible = 0;
    const visibleButtons: ToolbarButtons = new ToolbarButtons([]);
    const overflownButtons: ToolbarButtons = new ToolbarButtons([]);

    if (!containerRef) {
      return;
    }

    const elements = Array.from(containerRef.children).map((child: Element) => {
      return {
        child,
        width: Math.ceil(child.getBoundingClientRect().width),
      };
    });
    let stackIsFull = false;
    elements.forEach((element, index) => {
      if ((!stackIsFull && sumVisible + element.width <= width - MORE_BUTTON_WIDTH) || jsdomMode) {
        visibleButtons.addButton(buttonsToRender.getButtonByIndex(index));

        sumVisible += element.width + GAP_BETWEEN_BUTTONS;
      } else {
        stackIsFull = true;
        overflownButtons.addButton(buttonsToRender.getButtonByIndex(index));
      }
    });

    alwaysOverflownButtons.forEach(button => {
      overflownButtons.addButton(button);
    });

    onChange({
      visibleButtons,
      overflownButtons,
    });
  }, [width, toolbarButtons, containerRef]);

  return (
    <div
      style={{ visibility: 'hidden', position: 'absolute', display: 'flex' }}
      ref={setContainerRef}
    >
      {buttonsToRender.getButtonsElements()}
    </div>
  );
};

export const useSizeCalculator = ({
  width,
  toolbarButtons,
  onlyShownButtons,
}: SizeCalculatorProps) => {
  const [data, setData] = useState<SizeResult>(() =>
    getInitialSizeResult(toolbarButtons, onlyShownButtons)
  );

  const OverflowCalculator = useCallback(
    () => (
      <Overflow
        width={Number(width)}
        toolbarButtons={toolbarButtons}
        onChange={setData}
        onlyShownButtons={onlyShownButtons}
      />
    ),
    [width, toolbarButtons, onlyShownButtons, setData]
  );

  return { data, OverflowCalculator };
};
