import React, { useContext, useMemo, useState } from 'react';

import {
  EditorContext,
  PluginsContext,
  RicosContext,
  useTrackRender,
} from './../../../ricos-context/index.js';
import { getToolbarSettings, useToolbarSettings } from './../../../ricos-context/toolbar-context.js';
import { useIsExternalModalOpen } from './../../../ricos-modals/modal-service-provider.js';
import type { RicosPluginToolbar } from './../../../ricos-plugins/plugin-toolbar.js';
import type { IToolbarItemConfigTiptap, PluginToolbarIds } from './../../../ricos-types/index.js';
import { PluginNameToToolbarIdMap, ToolbarType } from './../../../ricos-types/index.js';
import { useToolbarBoundary } from './../../toolbar-boundary.js';

import { FloatingToolbar } from '../../components/FloatingToolbar/floating-toolbar.js';
import { MaxWidthCalculationWrapper } from '../../components/MaxWidthCalculationWrapper/max-width-calculation-wrapper.js';
import { Toolbar } from '../../components/Toolbar/index.js';
import { useIsVisible } from '../formatting/use-is-visible.js';
import { useIsToolbarEmpty } from '../use-is-toolbar-empty.js';
import { FLOATING_PLUGIN_TOOLBAR } from './data-hooks.js';
import { getReferenceElement } from './get-plugin-reference-element.js';
import { useDismissPluginToolbarOnOutsideClick } from './use-dismiss-plugin-toolbar-on-outside-click.js';

/**
 * Apply the consumer's plugin-toolbar filter/reorder. `filterButtons` takes
 * precedence over `filterItems` when both are provided — it receives the full
 * list, lets the consumer pick and reorder, and is what the V2
 * `toolbars.plugin.buttons` adapter emits.
 */
const applyPluginButtonsFilter = (
  items: IToolbarItemConfigTiptap[],
  nodeType: PluginToolbarIds,
  filterButtons: ((items: any[], nodeType: PluginToolbarIds) => any[]) | undefined,
  filterItems: ((item: any, nodeType: PluginToolbarIds) => boolean) | undefined
): IToolbarItemConfigTiptap[] => {
  if (filterButtons) {
    return filterButtons(items, nodeType);
  }
  if (filterItems) {
    return items.filter(item => filterItems(item, nodeType));
  }
  return items;
};

const PluginsToolbarContent = ({
  toolbar,
  boundary,
  filteredItemsConfig,
}: {
  toolbar: RicosPluginToolbar;
  boundary: HTMLElement;
  filteredItemsConfig: IToolbarItemConfigTiptap[];
}) => {
  useTrackRender('Plugin toolbar');

  const { languageDir, isMobile, t } = useContext(RicosContext);

  const [maxWidth, setMaxWidth] = useState(() => boundary?.clientWidth ?? 0);

  const itemsRenderers = useMemo(() => toolbar.getToolbarButtonsRenderers(), [toolbar]);

  const dataHook = `${FLOATING_PLUGIN_TOOLBAR} ${toolbar.pluginType ?? ''}`;

  return (
    <MaxWidthCalculationWrapper
      dir={languageDir}
      data-hook={dataHook}
      setMaxWidth={setMaxWidth}
      otherWrapper={boundary}
    >
      <Toolbar
        type="floating"
        isMobile={isMobile}
        toolbarItemsConfig={filteredItemsConfig}
        toolbarItemsRenderers={itemsRenderers}
        maxWidth={maxWidth}
        ariaLabel={t('PluginToolbar_AriaLabel')}
      />
    </MaxWidthCalculationWrapper>
  );
};

export const PluginsToolbar = () => {
  const plugins = useContext(PluginsContext);
  const ricosEditor = useContext(EditorContext);
  const boundary = useToolbarBoundary();
  const { portal } = useContext(RicosContext);
  const {
    adapter: { tiptapEditor },
  } = ricosEditor;

  const shownToolbar = plugins.getVisibleToolbar(tiptapEditor.state.selection, ricosEditor);
  const isVisible = useIsVisible();
  const isToolbarEmpty = useIsToolbarEmpty(ToolbarType.PLUGIN);
  const { filterItems, filterButtons } =
    useToolbarSettings(getToolbarSettings(ToolbarType.PLUGIN)) ?? {};

  const isEligibleToShow = !!shownToolbar && !!boundary && !isVisible && !isToolbarEmpty;
  const isExternalModalOpen = useIsExternalModalOpen();
  const isDismissedByOutsideClick = useDismissPluginToolbarOnOutsideClick(
    tiptapEditor,
    portal,
    isEligibleToShow,
    isExternalModalOpen
  );

  if (!shownToolbar || !boundary || isVisible || isToolbarEmpty || isDismissedByOutsideClick) {
    return null;
  }

  const selectedDOM = tiptapEditor.view.nodeDOM(tiptapEditor.state.selection.from);
  const isCropModeActive =
    selectedDOM instanceof HTMLElement &&
    !!selectedDOM.closest('[data-hook^="figure-"][data-cropping]');

  if (isCropModeActive) {
    return null;
  }

  // Run after the early-return guards. Some plugin button `getIcon` paths
  // throw if invoked in an incomplete state (e.g. before `boundary` is ready),
  // so this MUST stay below the guards above. Inline (no `useMemo`) — adding
  // a hook here would have to be unconditional and would re-introduce the
  // pre-guard timing bug.
  const nodeType = PluginNameToToolbarIdMap[shownToolbar.pluginType];
  const filteredItemsConfig = applyPluginButtonsFilter(
    shownToolbar.toToolbarItemsConfig(),
    nodeType,
    filterButtons,
    filterItems
  );

  if (filteredItemsConfig.length === 0) {
    return null;
  }

  const referenceElement = getReferenceElement(shownToolbar, tiptapEditor);

  if (!referenceElement) {
    return null;
  }

  return (
    <FloatingToolbar
      hideStrategy="escaped"
      boundary={boundary}
      referenceElement={referenceElement}
      placement="top"
    >
      <PluginsToolbarContent
        toolbar={shownToolbar}
        boundary={boundary}
        filteredItemsConfig={filteredItemsConfig}
      />
    </FloatingToolbar>
  );
};
